// ═══════════════════════════════════════════════
// AGENTGUARD — PermissionGate v1.0
// Glob-pattern tool-level allow/deny + audit
// ═══════════════════════════════════════════════

const config = {
  defaultAction: 'prompt',  // 'allow', 'deny', 'prompt'
  auditLog: true,
  logDestination: 'output', // 'postgres', 'webhook', 'file', 'output'
  webhookUrl: '',
  rules: [
    // ─── Read Operations (Safe) ───
    { tool: 'bash',     pattern: 'ls *',       action: 'allow' },
    { tool: 'bash',     pattern: 'cat *',      action: 'allow' },
    { tool: 'bash',     pattern: 'grep *',     action: 'allow' },
    { tool: 'bash',     pattern: 'find *',     action: 'allow' },
    { tool: 'bash',     pattern: 'head *',     action: 'allow' },
    { tool: 'bash',     pattern: 'tail *',     action: 'allow' },
    { tool: 'bash',     pattern: 'wc *',       action: 'allow' },
    { tool: 'bash',     pattern: 'echo *',     action: 'allow' },
    { tool: 'bash',     pattern: 'pwd',        action: 'allow' },
    { tool: 'bash',     pattern: 'whoami',     action: 'allow' },

    // ─── Git (Read) ───
    { tool: 'bash',     pattern: 'git status*', action: 'allow' },
    { tool: 'bash',     pattern: 'git log*',    action: 'allow' },
    { tool: 'bash',     pattern: 'git diff*',   action: 'allow' },
    { tool: 'bash',     pattern: 'git branch*', action: 'allow' },

    // ─── Git (Write — Gate) ───
    { tool: 'bash',     pattern: 'git commit*',  action: 'prompt' },
    { tool: 'bash',     pattern: 'git push*',    action: 'prompt' },
    { tool: 'bash',     pattern: 'git merge*',   action: 'prompt' },

    // ─── Package Managers ───
    { tool: 'bash',     pattern: 'npm test*',    action: 'allow' },
    { tool: 'bash',     pattern: 'npm install*', action: 'prompt' },
    { tool: 'bash',     pattern: 'pip install*', action: 'prompt' },

    // ─── Destructive (Block) ───
    { tool: 'bash',     pattern: 'rm -rf*',     action: 'deny' },
    { tool: 'bash',     pattern: 'rm -r *',     action: 'deny' },
    { tool: 'bash',     pattern: 'sudo rm*',    action: 'deny' },
    { tool: 'bash',     pattern: '*DROP TABLE*', action: 'deny' },
    { tool: 'bash',     pattern: '*DROP DATABASE*', action: 'deny' },
    { tool: 'bash',     pattern: '*shutdown*',   action: 'deny' },
    { tool: 'bash',     pattern: '*reboot*',     action: 'deny' },
    { tool: 'bash',     pattern: 'chmod 777*',   action: 'deny' },
    { tool: 'bash',     pattern: '*mkfs*',       action: 'deny' },
    { tool: 'bash',     pattern: '*dd if=*',     action: 'deny' },

    // ─── HTTP ───
    { tool: 'http',     pattern: 'GET *',       action: 'allow' },
    { tool: 'http',     pattern: 'POST *',      action: 'prompt' },
    { tool: 'http',     pattern: 'PUT *',       action: 'prompt' },
    { tool: 'http',     pattern: 'DELETE *',    action: 'deny' },

    // ─── Database ───
    { tool: 'database', pattern: 'SELECT *',    action: 'allow' },
    { tool: 'database', pattern: 'INSERT *',    action: 'prompt' },
    { tool: 'database', pattern: 'UPDATE *',    action: 'prompt' },
    { tool: 'database', pattern: 'DELETE *',    action: 'deny' },
    { tool: 'database', pattern: 'DROP *',      action: 'deny' },
    { tool: 'database', pattern: 'ALTER *',     action: 'deny' },

    // ─── File Operations ───
    { tool: 'file',     pattern: 'read *',      action: 'allow' },
    { tool: 'file',     pattern: 'write *',     action: 'prompt' },
    { tool: 'file',     pattern: 'delete *',    action: 'deny' }
  ]
};

const input = $input.first().json;
const toolName = (input.toolName || input.tool || '').toLowerCase();
const toolInput = input.toolInput || input.input || input.command || '';

// ─── Glob Matcher ───
function globMatch(pattern, text) {
  const escapedPattern = pattern
    .replace(/[.+^${}()|[\]\\]/g, '\\$&')
    .replace(/\*/g, '.*');
  return new RegExp(`^${escapedPattern}$`, 'i').test(text);
}

// ─── Rule Evaluation ───
function evaluate(tool, input) {
  for (const rule of config.rules) {
    const toolMatch = rule.tool === '*' || globMatch(rule.tool, tool);
    const inputMatch = rule.pattern === '*' || globMatch(rule.pattern, input);

    if (toolMatch && inputMatch) {
      return {
        matched: true,
        rule: rule,
        action: rule.action
      };
    }
  }

  // No rule matched — use default
  return {
    matched: false,
    rule: null,
    action: config.defaultAction
  };
}

// ─── Execute ───
const evaluation = evaluate(toolName, toolInput);

const auditEntry = {
  timestamp: new Date().toISOString(),
  tool: toolName,
  input: toolInput.slice(0, 500), // Truncate for audit
  ruleMatched: evaluation.matched ? `${evaluation.rule.tool}:${evaluation.rule.pattern}` : 'default',
  action: evaluation.action,
  decision: evaluation.action === 'allow' ? 'APPROVED' : evaluation.action === 'deny' ? 'BLOCKED' : 'PENDING_APPROVAL'
};

return [{
  json: {
    // Decision
    action: evaluation.action,
    approved: evaluation.action === 'allow',
    blocked: evaluation.action === 'deny',
    needsApproval: evaluation.action === 'prompt',

    // Context for the model
    modelMessage: evaluation.action === 'deny' 
      ? `Permission denied: ${toolName} with input matching '${evaluation.rule?.pattern || 'default deny'}' is blocked by policy.`
      : evaluation.action === 'prompt'
        ? `This action requires operator approval. Waiting for confirmation.`
        : null,

    // Rule info
    ruleMatched: evaluation.matched,
    matchedPattern: evaluation.rule ? `${evaluation.rule.tool}:${evaluation.rule.pattern}` : 'default',

    // Pass through original request
    toolName,
    toolInput,
    originalRequest: input,

    // Audit
    audit: config.auditLog ? auditEntry : null,

    _agTimestamp: new Date().toISOString()
  }
}];
